head.script:
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
gBondYn = js_bond_yn;
scwin.gParamObj = new Array(9);

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        await scwin.setCode();
        $c.cm.PanelToGroupBox(panel_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26700.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26700.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26700.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF26700.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "제출현황목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26700.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Snd_onclick
 * @description 「금감원 전송대상 내역」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Snd_onclick = async function() {
    try {
        await scwin.submitObjPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26700.btn_Snd_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        await scwin.read(grd_Grid, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26700.grd_Grid_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_SCHDL_DD",
        action : "/SubmitStatus.do",
        ref : "",
        target : "dts_SCHDL_DD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 최근일자를 셋팅
    const toDate = $c.ut.cGetToday("yyyymmdd");
    let sDate = '';
    for (let i = 1; i <= dts_SCHDL_DD.getRowCount(); i++) {
        sDate = dts_SCHDL_DD.getCellData(i, "VALUE");
        if (parseInt(toDate) > parseInt(dts_SCHDL_DD.getCellData(i, "VALUE"))) {
            sDate = dts_SCHDL_DD.getCellData(i - 1, "VALUE");
            break;
        }
    }
    // alert('[sDate]'+sDate);
    cmb_SCHDL_DD.setValue(sDate);
    rdo_MKT_ID.setValue(js_market);
    if (js_market === "9") {
        rdo_MKT_ID.setDisabled(false);
        rdo_MKT_ID.setValue("1");
    } else {
        // 콘트롤 잠그기.
        rdo_MKT_ID.setDisabled(true);
    }
    // alert('[js_dep_cd]'+js_dep_cd + "_" + js_market);

    if (scwin.gDepCd !== "ZSYS") {
        btn_Snd.hide();
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const vMKT_ID = rdo_MKT_ID.getValue();
    const vSCHDL_DD = cmb_SCHDL_DD.getValue();
    const vDEP_CD = cmb_DEP_CD.getValue();

    // var vYYYY= getObjectValue(cmb_YYYY);

    if (vMKT_ID === "9" || vMKT_ID === "") {
        await $c.win.alert("시장구분을 선택해 주세요");
        return false;
    }
    url += "&MKT_ID=" + vMKT_ID;
    url += "&SCHDL_DD=" + vSCHDL_DD;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&BOND_YN=" + gBondYn;
    url += "&SCREN_ID=" + 'ULDSTF26700.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/SubmitStatus.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function(GridID, row, colid) {
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    // var vIBAS_ACNTCLS_MM = objDataID.NameString(row, "BAS_ACNTCLS_MM");

    if (row < 1) return;
    if (colid === "WRTRPT_KIND_NM") {
        const CMD = "R";
        const vIBAS_YY = objDataID.getCellData(row, "BAS_YY");
        const vIBAS_ACNTCLS_MM = objDataID.getCellData(row, "BAS_ACNTCLS_MM");
        const vIWRTRPT_KIND_CD = objDataID.getCellData(row, "WRTRPT_KIND_CD");
        const vIMKT_ID = rdo_MKT_ID.getValue();
        const vIBAS_ACNTCLS_MM_YY = objDataID.getCellData(row, "BAS_ACNTCLS_MM_YY");
        const vIWRTRPT_KIND_CDNM = objDataID.getCellData(row, "WRTRPT_KIND_NM");
        const vIDEP_CD = cmb_DEP_CD.getValue();
        const vIDEP_CDNM = cmb_DEP_CD.getText();
        const vIWRTRPT_SUBMIT_SCHDL_DD = cmb_SCHDL_DD.getText();
        let url = "/dsclsrch/ULDSTF26701.gfm?";
        url += "&BAS_YY=" + vIBAS_YY;
        url += "&BAS_ACNTCLS_MM=" + vIBAS_ACNTCLS_MM;
        url += "&WRTRPT_KIND_CD=" + vIWRTRPT_KIND_CD;
        url += "&BAS_ACNTCLS_MM_YY=" + vIBAS_ACNTCLS_MM_YY;
        url += "&WRTRPT_KIND_CDNM=" + vIWRTRPT_KIND_CDNM;
        url += "&DEP_CD=" + vIDEP_CD;
        url += "&DEP_CDNM=" + vIDEP_CDNM;
        url += "&MKT_ID=" + vIMKT_ID;
        url += "&WRTRPT_SUBMIT_SCHDL_DD=" + vIWRTRPT_SUBMIT_SCHDL_DD;
        if (await scwin.setParam(CMD, vIBAS_YY, vIBAS_ACNTCLS_MM, vIWRTRPT_KIND_CD, vIBAS_ACNTCLS_MM_YY, vIWRTRPT_KIND_CDNM, vIDEP_CDNM, vIMKT_ID, vIWRTRPT_SUBMIT_SCHDL_DD)) // formal arguments

        {
            // frame.CreateDialogFrame("child01", "/dsclsrch/ULDSTF26601.gfm", "상세조회", 10, 10, 810,650, "window");
            $c.frame.path("../../").GWinOpen("child01", url, "상세조회", 20, 20, 1255, 640 + 40, "");
        }
    }
};

/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    if (js_market !== "9") {
        panel_mkt.hide();
    }
};

/**
 * @method
 * @name submitObjPopup
 * @description 금감원 전송대상 내역 팝업창 띄우기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submitObjPopup = async function() {
    const options = {
        id: "ULDSTF26702",
        title: "보고서 제출대상 법인목록",
        type: "browserPopup",
        width: "1077px",
        height: "784px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclsrch/ULDSTF26702.gfm", options);
};
